-- CreateEnum
CREATE TYPE "TicketRequestDecision" AS ENUM ('APPROVE', 'REJECT');

-- AlterTable
ALTER TABLE "tickets" ADD COLUMN     "ticket_request_id" TEXT;

-- CreateTable
CREATE TABLE "ticket_requests" (
    "id" TEXT NOT NULL,
    "user_id" TEXT NOT NULL,
    "ticket_type_id" TEXT NOT NULL,
    "event_id" TEXT NOT NULL,
    "intent" "TicketRequestIntent" NOT NULL,
    "status" "TicketRequestStatus" NOT NULL DEFAULT 'PENDING',
    "stripe_checkout_session_id" TEXT,
    "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updated_at" TIMESTAMP(3) NOT NULL,

    CONSTRAINT "ticket_requests_pkey" PRIMARY KEY ("id")
);

